import os
from typing import Dict, Any, Optional, List
import requests


class PerspectiveContentSafety:
    API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"

    DEFAULT_THRESHOLDS = {
        "TOXICITY": 0.8,
        "SEVERE_TOXICITY": 0.7,
        "INSULT": 0.85,
        "THREAT": 0.6,
        "PROFANITY": 0.9,
        "IDENTITY_ATTACK": 0.7,
        "SEXUALLY_EXPLICIT": 0.8,
    }

    def __init__(
        self,
        api_key: Optional[str] = None,
        thresholds: Optional[Dict[str, float]] = None,
        languages: Optional[List[str]] = None,
        timeout: int = 15,
    ) -> None:
        self.api_key = api_key or os.environ.get("PERSPECTIVE_API_KEY")
        if not self.api_key:
            raise ValueError("Missing Perspective API key. Set PERSPECTIVE_API_KEY.")
        self.thresholds = thresholds or self.DEFAULT_THRESHOLDS.copy()
        self.languages = languages
        self.timeout = timeout

    def analyze(self, text: str) -> Dict[str, Any]:
        if not isinstance(text, str) or not text.strip():
            raise ValueError("text must be a non-empty string")

        requested_attributes = {name: {} for name in self.thresholds.keys()}
        payload: Dict[str, Any] = {
            "comment": {"text": text},
            "requestedAttributes": requested_attributes,
            "doNotStore": True,
        }
        if self.languages:
            payload["languages"] = self.languages

        response = requests.post(
            self.API_URL,
            params={"key": self.api_key},
            json=payload,
            timeout=self.timeout,
        )
        response.raise_for_status()
        data = response.json()

        attribute_scores = data.get("attributeScores", {})
        scores: Dict[str, float] = {}
        violations: Dict[str, Dict[str, float]] = {}

        for category, threshold in self.thresholds.items():
            summary = attribute_scores.get(category, {}).get("summaryScore", {})
            value = float(summary.get("value", 0.0))
            scores[category] = value
            if value >= threshold:
                violations[category] = {
                    "score": value,
                    "threshold": float(threshold),
                }

        allowed = len(violations) == 0

        return {
            "provider": "Perspective API",
            "allowed": allowed,
            "scores": scores,
            "thresholds": {k: float(v) for k, v in self.thresholds.items()},
            "violations": violations,
            "raw_response": data,
        }


def allow_text(
    text: str,
    thresholds: Optional[Dict[str, float]] = None,
    api_key: Optional[str] = None,
    languages: Optional[List[str]] = None,
) -> Dict[str, Any]:
    moderator = PerspectiveContentSafety(
        api_key=api_key,
        thresholds=thresholds,
        languages=languages,
    )
    return moderator.analyze(text)
